fn extract_position(path: string) -> string {
  intent "경로에서 position 추출"
  do
    // "/api/plugins/ui/sidebar" → "sidebar"
    return "sidebar"  // TODO: 실제 구현
  end
}

fn read_file(path: string) -> string {
  intent "파일 읽기"
  do
    match file_io::read_file(path)
      Ok(content) => {
        log_file_operation("READ", path, "✅ 성공")
        return content
      }
      Err(e) => {
        log_file_operation("READ", path, "❌ 실패: " + e.message)
        return ""
      }
    end
  end
}

fn create_html_response(html: string) -> HttpResponse {
  intent "HTML 응답 생성"
  do
    let headers = {
      "Content-Type": "text/html; charset=utf-8",
      "Connection": "keep-alive"
    }

    return HttpResponse {
      status: 200,
      statusText: "OK",
      headers: headers,
      body: html,
      bodyBytes: []
    }
  end
}

fn create_json_response(status: i32, json: string) -> HttpResponse {
  intent "JSON 응답 생성"
  do
    let headers = {
      "Content-Type": "application/json; charset=utf-8",
      "Connection": "keep-alive"
    }

    return HttpResponse {
      status: status,
      statusText: "OK",
      headers: headers,
      body: json,
      bodyBytes: []
    }
  end
}

fn create_error_response(status: i32, message: string) -> HttpResponse {
  intent "에러 응답 생성"
  do
    let json = "{\"error\":\"" + message + "\"}"

    let headers = {
      "Content-Type": "application/json; charset=utf-8",
      "Connection": "keep-alive"
    }

    return HttpResponse {
      status: status,
      statusText: "Error",
      headers: headers,
      body: json,
      bodyBytes: []
    }
  end
}
